<template><div v-if="game" class="page-wrap detail-wrap"><div class="breadcrumbs"><RouterLink to="/">首页</RouterLink><span>/</span><RouterLink to="/games">发现游戏</RouterLink><span>/</span><span>{{ game.title }}</span></div><section class="detail-hero"><GameCover :src="game.cover" :alt="game.coverAlt" :title="game.title" tone="blue"/><div class="detail-intro"><span class="eyebrow">{{ categoryNames }}</span><h1>{{ game.title }}</h1><p class="detail-subtitle">{{ game.subtitle }}</p><p>{{ game.description }}</p><div class="tag-row"><span v-for="tag in game.tags" :key="tag">{{ tag }}</span></div><div class="detail-actions"><button class="button primary" v-for="link in safeDownloads" :key="link.id" @click="openLink(link.url)">{{ link.label || link.provider || '网盘获取' }} ↗ <small v-if="link.extractCode">提取码 {{ link.extractCode }}</small></button><button class="button primary" v-if="officialUrl" @click="openLink(officialUrl)">前往官方获取 ↗</button><button class="button secondary" v-if="!safeDownloads.length&&!officialUrl" disabled>暂未提供获取链接</button><button class="button secondary" @click="toggleFavorite(game.id)">{{ favorites.includes(game.id)?'♥ 已收藏':'♡ 收藏游戏' }}</button></div><p class="license-note">{{ game.licenseNote }}</p></div></section><div class="detail-columns"><article class="detail-content"><section><h2>游戏介绍</h2><p>{{ game.description }}</p></section><section v-if="game.features?.length"><h2>游戏特色</h2><ul class="feature-list"><li v-for="f in game.features" :key="f">{{ f }}</li></ul></section><section v-if="game.controls?.length"><h2>操作说明</h2><p v-for="c in game.controls" :key="c">{{ c }}</p></section><section v-if="game.requirements?.length"><h2>运行要求</h2><p v-for="r in game.requirements" :key="r">{{ r }}</p></section><section v-if="game.faqs?.length"><h2>常见问题</h2><details v-for="f in game.faqs" :key="f.question"><summary>{{ f.question }}</summary><p>{{ f.answer }}</p></details></section></article><aside class="spec-card"><h3>游戏信息</h3><div v-for="row in specs" :key="row[0]" class="spec-row"><span>{{ row[0] }}</span><b>{{ row[1] }}</b></div><h3>获取与授权</h3><p class="license-note">{{ game.licenseStatus==='permission_confirmed'?'已核实分发权限':game.licenseStatus==='official_only'?'仅提供官方获取入口':'授权信息待核实' }}</p></aside></div><section v-if="related.length" class="related-section"><div class="section-heading"><div><span class="eyebrow">KEEP EXPLORING</span><h2>你可能也喜欢</h2></div></div><div class="game-grid"><GameCard v-for="g in related" :key="g.id" :game="g"/></div></section></div><div v-else class="empty-state page-wrap"><h1>暂时找不到这款游戏</h1><RouterLink to="/games" class="button primary">返回游戏库</RouterLink></div></template>
<script setup>
import {inject,computed} from 'vue';import {useRoute} from 'vue-router';import GameCover from '../components/GameCover.vue';import GameCard from '../components/GameCard.vue'
const data=inject('siteData'),route=useRoute(),favorites=inject('favorites'),toggleFavorite=inject('toggleFavorite'),game=computed(()=>data.games.find(g=>g.slug===route.params.slug&&g.published)),categoryNames=computed(()=>game.value?.categoryIds?.map(id=>data.categories.find(c=>c.id===id)?.name).filter(Boolean).join(' · ')),safeDownloads=computed(()=>game.value?.published&&!game.value?.demoOnly&&game.value?.licenseStatus==='permission_confirmed'?(game.value.downloadLinks||[]).filter(x=>x.enabled&&valid(x.url)):[]),officialUrl=computed(()=>game.value?.licenseStatus==='official_only'&&valid(game.value?.sourceUrl)?game.value.sourceUrl:''),related=computed(()=>game.value?.relatedGameIds?.map(id=>data.games.find(g=>g.id===id&&g.published)).filter(Boolean)||[]),specs=computed(()=>[['开发者',game.value?.developer],['发行年份',game.value?.releaseYear],['版本',game.value?.version],['平台',game.value?.platforms?.join('、')],['语言',game.value?.language?.join('、')],['游戏大小',game.value?.gameSize]].filter(x=>x[1]));function valid(x){try{return ['https:','http:'].includes(new URL(x).protocol)}catch{return false}}function openLink(x){if(valid(x))window.open(x,'_blank','noopener,noreferrer')}</script>
